from pathlib import Path

from app.services import users

DATA_DIR = Path(__file__).resolve().parents[2] / "data"


def _is_safe_relative_path(raw: str) -> bool:
    """Return True when raw is a safe path relative to the data directory."""
    if raw == "":
        return True
    return all(
        segment and segment not in (".", "..") and "\x00" not in segment
        for segment in raw.split("/")
    )


def handle_get_user(params: dict) -> tuple[int, dict]:
    raw = params.get("id")
    if not isinstance(raw, str) or not raw.isdigit():
        return 400, {"error": "invalid id"}
    user = users.get_user(int(raw))
    if user is None:
        return 404, {"error": "not found"}
    return 200, user


def handle_dir_size(params: dict) -> tuple[int, dict]:
    raw = params.get("dir", "")
    if not isinstance(raw, str) or not _is_safe_relative_path(raw):
        return 400, {"error": "invalid path"}

    base = DATA_DIR.resolve()
    target = base if raw == "" else (base / raw).resolve()
    if not target.is_relative_to(base):
        return 400, {"error": "invalid path"}
    if not target.is_dir():
        return 404, {"error": "not found"}

    total = 0
    for path in target.rglob("*"):
        if path.is_file():
            total += path.stat().st_size
    return 200, {"bytes": total}
